<?php
session_start();
require_once __DIR__ . '/../config/config.php';
$userId=max(1,(int)($_GET['user_id']??0));
$viewerId=(int)($_SESSION['user_id']??0);
$stmt=$pdo->prepare('SELECT user_id,display_name,bio,profile_image,followers_count,created_at FROM users WHERE user_id=?');
$stmt->execute([$userId]);
$profile=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$profile){http_response_code(404);exit('ไม่พบโปรไฟล์สมาชิก');}
$isOwnProfile=$viewerId===$userId;
$tab=($_GET['tab']??'exchange')==='used'?'used':'exchange';
$page=max(1,(int)($_GET['page']??1));$perPage=12;$offset=($page-1)*$perPage;
$exchangeCountStmt=$pdo->prepare("SELECT COUNT(*) FROM exchanges WHERE owner_id=? AND status<>'completed'");$exchangeCountStmt->execute([$userId]);$exchangeTotal=(int)$exchangeCountStmt->fetchColumn();
$usedCountStmt=$pdo->prepare("SELECT COUNT(*) FROM books WHERE seller_type='user' AND seller_id=? AND status='available' AND book_type='used'");$usedCountStmt->execute([$userId]);$usedTotal=(int)$usedCountStmt->fetchColumn();
$total=$tab==='used'?$usedTotal:$exchangeTotal;$pages=max(1,(int)ceil($total/$perPage));
if($tab==='used'){$booksStmt=$pdo->prepare("SELECT * FROM books WHERE seller_type='user' AND seller_id=:owner AND status='available' AND book_type='used' ORDER BY created_at DESC LIMIT :limit OFFSET :offset");}
else{$booksStmt=$pdo->prepare("SELECT * FROM exchanges WHERE owner_id=:owner AND status<>'completed' ORDER BY created_at DESC LIMIT :limit OFFSET :offset");}
$booksStmt->bindValue(':owner',$userId,PDO::PARAM_INT);$booksStmt->bindValue(':limit',$perPage,PDO::PARAM_INT);$booksStmt->bindValue(':offset',$offset,PDO::PARAM_INT);$booksStmt->execute();$books=$booksStmt->fetchAll(PDO::FETCH_ASSOC);
$name=$profile['display_name']?:'สมาชิกวนวรรณ';
function exchangeProfileImage(?string $value):?string{if(!$value)return null;if(preg_match('#^https?://#i',$value))return $value;$value=ltrim(str_replace('\\','/',$value),'/');return str_starts_with($value,'uploads/')?'/pages/'.$value:'/assets/image/books/'.$value;}
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($name)?> - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css">
<style>*{box-sizing:border-box}.profile-wrap{max-width:1160px;margin:auto;padding:38px 40px 80px}.breadcrumb{color:var(--text-muted);margin-bottom:38px}.breadcrumb a{color:inherit;text-decoration:none}.profile-hero{display:grid;grid-template-columns:140px 1fr auto;gap:30px;align-items:center;padding:30px;border:1px solid #e2ddd7;border-radius:18px;background:#fffaf7;margin-bottom:32px}.profile-avatar{width:125px;height:125px;border-radius:50%;display:grid;place-items:center;background:var(--accent-pink-light);color:var(--primary-color);font-size:48px;font-weight:700;overflow:hidden}.profile-avatar img{width:100%;height:100%;object-fit:cover}.profile-name{font-size:32px;color:var(--secondary-color);margin:0 0 8px}.profile-desc{color:var(--text-muted);margin:0;line-height:1.7}.profile-stats{display:flex;gap:46px;margin-top:22px}.stat strong,.stat span{display:block}.stat strong{font-size:24px;color:var(--secondary-color)}.stat span{font-size:13px;color:var(--text-muted)}.profile-actions{display:grid;gap:10px}.profile-btn{min-width:145px;height:44px;border:1px solid #d3948b;border-radius:8px;display:grid;place-items:center;text-decoration:none;font:inherit;font-weight:600;cursor:pointer}.follow{background:#d3948b;color:#fff}.follow.is-following,.message{background:#fff;color:#b66f68}.content-tabs{display:flex;gap:14px;margin-bottom:30px}.content-tabs a{min-width:230px;padding:12px 24px;border-radius:24px;background:var(--accent-pink-light);color:var(--secondary-color);text-align:center;text-decoration:none;font-weight:600}.content-tabs a.active{background:var(--secondary-color);color:#fff}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.section-head h2{color:var(--secondary-color);font-size:27px;margin:0}.exchange-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.exchange-grid>.book-card{height:100%}.empty{grid-column:1/-1;text-align:center;padding:80px 20px;border:1px dashed #d8ddd4;border-radius:14px;color:var(--text-muted)}.pagination{display:flex;justify-content:center;gap:10px;margin-top:45px}.pagination a{width:42px;height:42px;display:grid;place-items:center;border:1px solid var(--secondary-color);border-radius:8px;color:var(--secondary-color);text-decoration:none}.pagination a.active{background:var(--secondary-color);color:#fff}@media(max-width:900px){.profile-hero{grid-template-columns:120px 1fr}.profile-actions{grid-column:2;display:flex}}@media(max-width:600px){.profile-wrap{padding:25px 18px 60px}.profile-hero{grid-template-columns:1fr;text-align:center}.profile-avatar{margin:auto}.profile-actions{grid-column:auto;justify-content:center;flex-wrap:wrap}.profile-stats{justify-content:center}.content-tabs{overflow-x:auto}.content-tabs a{min-width:210px}.exchange-grid{grid-template-columns:1fr}}</style></head><body>
<?php require __DIR__.'/../components/header.php';?><main class="profile-wrap">
<section class="profile-hero"><div class="profile-avatar"><?php if($avatar=exchangeProfileImage($profile['profile_image']??null)):?><img src="<?=htmlspecialchars($avatar)?>" alt="<?=htmlspecialchars($name)?>"><?php else:?><?=htmlspecialchars(mb_substr($name,0,1))?><?php endif;?></div><div><h1 class="profile-name"><?=htmlspecialchars($name)?></h1><p class="profile-desc"><?=nl2br(htmlspecialchars($profile['bio']?:'สมาชิกชุมชนนักอ่านวนวรรณ พร้อมแบ่งปันและส่งต่อหนังสือผ่านการแลกเปลี่ยน'))?></p><div class="profile-stats"><div class="stat"><strong data-followers-type="user" data-followers-id="<?=$userId?>"><?=number_format((int)$profile['followers_count'])?></strong><span>ผู้ติดตาม</span></div><div class="stat"><strong><?=number_format($exchangeTotal+$usedTotal)?></strong><span>โพสต์ทั้งหมด</span></div><div class="stat"><strong><?=date('Y',strtotime($profile['created_at']))?></strong><span>เป็นสมาชิกตั้งแต่</span></div></div></div><?php if(!$isOwnProfile):?><div class="profile-actions"><?php $follow_type='user';$follow_id=$userId;$follow_class='profile-btn follow';require __DIR__.'/../components/follow_button.php';?><a class="profile-btn message" href="<?=$viewerId?'/pages/chat.php?seller_type=user&amp;seller_id='.$userId:'/pages/login.php'?>">ส่งข้อความ</a></div><?php endif;?></section>
<nav class="content-tabs"><a class="<?=$tab==='exchange'?'active':''?>" href="?user_id=<?=$userId?>&tab=exchange">หนังสือแลกเปลี่ยน (<?=number_format($exchangeTotal)?>)</a><a class="<?=$tab==='used'?'active':''?>" href="?user_id=<?=$userId?>&tab=used">หนังสือมือสองที่ขาย (<?=number_format($usedTotal)?>)</a></nav>
<section><div class="section-head"><h2><?=$tab==='used'?'หนังสือมือสองที่กำลังขาย':'หนังสือสำหรับแลกเปลี่ยน'?></h2><span><?=number_format($total)?> รายการ</span></div><div class="exchange-grid">
<?php if(!$books):?><div class="empty"><?=$tab==='used'?'สมาชิกคนนี้ยังไม่มีหนังสือมือสองที่กำลังขาย':'สมาชิกคนนี้ยังไม่มีรายการหนังสือสำหรับแลกเปลี่ยน'?></div><?php else:foreach($books as $row){$isUsed=$tab==='used';$book=['id'=>(int)$row[$isUsed?'book_id':'exchange_id'],'title'=>$row['title'],'author'=>$row['author']??'','price'=>$isUsed?(float)$row['price']:0,'badge'=>$isUsed?'มือสอง':'แลกเปลี่ยน','image'=>exchangeProfileImage($row['image_cover']??null)];$card_type=$isUsed?'used':'exchange';require __DIR__.'/../components/book_card.php';}endif;?></div>
<?php if($pages>1):?><nav class="pagination"><?php for($p=1;$p<=$pages;$p++):?><a class="<?=$p===$page?'active':''?>" href="?user_id=<?=$userId?>&tab=<?=$tab?>&page=<?=$p?>"><?=$p?></a><?php endfor;?></nav><?php endif;?></section></main><?php require __DIR__.'/../components/footer.php';?></body></html>
